// Librairie : TU appelles le code, tu gardes le contrôle
import { formatDate } from 'date-fns';
console.log(formatDate(new Date(), 'dd/MM/yyyy'));

// Framework : LUI appelle ton code (inversion de contrôle)
// React décide QUAND appeler ton composant
function MonComposant() {
  return <h1>Bonjour</h1>;
}
// -> React contrôle le cycle de vie, pas toi

// Même un hook personnalisé reste soumis aux règles de React
function useCompteur() {
  return useState(0);
}

// React : JSX, logique et affichage dans la même fonction
function Bouton({ label, onClick }) {
  return <button onClick={onClick}>{label}</button>;
}

// Vue : template séparé, syntaxe déclarative dans le HTML
// <template><button @click="onClick">{{ label }}</button></template>

// Angular : classe + décorateur, TypeScript imposé
// @Component({ selector: 'app-bouton', template: '<button (click)="onClick()">{{label}}</button>' })
// class BoutonComponent { @Input() label; @Output() onClick = new EventEmitter(); }

// Angular ajoute par défaut le binding bidirectionnel (ngModel)
// <input [(ngModel)]="label">

// Node.js : accès fichier système libre par défaut, modules via npm
const fs = require('fs');
fs.readFileSync('data.txt');

// Deno : sécurité par défaut, permissions explicites requises
// deno run --allow-read script.ts
Deno.readTextFileSync('data.txt');

// Bun : compatible Node, mais runtime et bundler tout-en-un, très rapide au démarrage
import { readFileSync } from 'fs';
readFileSync('data.txt');

// Bun et Deno supportent aussi le top-level await nativement
console.log(import.meta.url);

// Avant bundling : plusieurs fichiers séparés
// utils.js
export function addition(a, b) { return a + b; }
// main.js
import { addition } from './utils.js';
console.log(addition(2, 3));

// Après bundling (simplifié) : un seul fichier optimisé
// (function() { function addition(a,b){return a+b} console.log(addition(2,3)) })();

